using System.ComponentModel.DataAnnotations;

namespace INKED.Application.ProductCategories;

/// <summary>Data the client sends to create a product category. CategoryID is generated by SQL Server.</summary>
public class CreateProductCategoryDto
{
    /// <summary>VARCHAR(50), required, unique, not blank.</summary>
    [Required, StringLength(50, MinimumLength = 1)]
    public string CategoryName { get; set; } = string.Empty;

    /// <summary>Must be one of: Apparel/Print, Tailoring, Embroidery/Enamel, Paper.</summary>
    [Required, StringLength(20, MinimumLength = 1)]
    public string ProductionType { get; set; } = string.Empty;
}
